from pathlib import Path
p=Path('PROJECT_REQUIREMENTS.md');s=p.read_text()
s=s.replace('Movie resolution changes on session reload explicitly require target rebuilding and are not yet supported; native export/shading parity remains unverified.','Movie resolution changes on session reload are now supported through coordinated target replacement; native export/shading parity remains unverified.')
s=s.replace('Changing target dimensions during playback still needs image/framebuffer/readback lifecycle and presentation-extent integration.','Changing target dimensions is now integrated with image/framebuffer/readback lifecycle and per-frame presentation extent.')
s=s.replace('Readback and presentation extent changes remain to be coordinated before resolution-changing reloads are supported.','Readback and presentation extent changes are now coordinated during resolution-changing reloads.')
s=s.replace('GPU consumption of changed frame dimensions, readback resizing and presentation updates remain unfinished.','GPU consumption of changed frame dimensions, readback resizing and presentation updates are now integrated and verified below.')
s+='\nMovie-size session reload now replaces color/depth/framebuffer and readback storage after preceding GPU work completes. Replacement resources are constructed before the old target is released, and presentation receives that frame\'s dimensions explicitly. A controlled 3840×2160 -> 640×480 -> 3840×2160 reload passed in both prefetch modes: the smaller frame matched an independent target, restored 4K pixels matched their reference, and presenter aspect fits followed every extent. Capture-free reload used zero GPU readbacks/output writes. See outputs/sfm64-movie-target-reload-gpu.json and outputs/sfm64-movie-target-reload-gpu-only.json. Allocation-failure injection, broad session/device compatibility, native renderer/export parity and full editor functionality remain unfinished or unverified.\n'
p.write_text(s)
